import{Q as e,et as t,f as n,g as r,nt as i}from"./client-BfQVG9-m.js";import{a}from"./badge-BCcl7-td.js";import{n as o}from"./context-BhOZ7n6B.js";import{l as s}from"./_intel-DxrcYqxZ.js";import{Bt as c,Ft as l,Ht as u,Ut as d,Vt as f,Wt as p,ft as m,zt as h}from"./index-Ck2CFqtD.js";import{n as g,t as _}from"./api-C14M3g7n.js";var v=n(`circle-dot`,[[`circle`,{cx:`12`,cy:`12`,r:`10`,key:`1mglay`}],[`circle`,{cx:`12`,cy:`12`,r:`1`,key:`41hilf`}]]);e(`recordings`,{en:{title:`Recordings`,subtitle:`Privileged session recording — every administrative action on a recorded surface is captured as a hash-chained frame, anchored to the evidence ledger.`,search:{field:`Search field`,subject:`Subject contains`,grant:`Grant ID`,input:`Recording search`,subjectPlaceholder:`Subject text`,grantPlaceholder:`Exact grant ID`,submit:`Search`,clear:`Clear`},allStatuses:`All statuses`,filterByStatus:`Filter by status`,filterBySealReason:`Filter by seal reason`,allSealReasons:`All seal reasons`,filterOpenedAfter:`Opened after`,filterOpenedBefore:`Opened before`,sealReasonOption:{idle:`Idle`,closed:`Closed`,breakglass_review:`Break-glass review`,sweep:`Sweep`,consent_change:`Consent change`},status:{active:`Active`,sealed:`Sealed`},kind:{user:`User`,token:`Token`},cols:{subject:`Subject`,kind:`Kind`,status:`Status`,opened:`Opened`,frames:`Frames written`,flags:`Flags`,sealReason:`Seal reason`},badge:{gap:`GAP`,gapHint:`Frames were reserved but never written — the recording has a permanent, evident gap.`,breakglass:`Break-glass`,breakglassHint:`Opened under a break-glass grant — always recorded.`},empty:{title:`No recording sessions yet`,description:`When operators act on a recorded privileged surface, their sessions appear here.`},notice:{strip:`This is a recorded privileged surface — actions are captured to the evidence ledger.`},consent:{title:`Recording notice (AC-8)`,body:`Privileged actions on this control plane are recorded: each administrative request is captured as a hash-chained frame anchored to the evidence ledger — route shape, identifiers and a one-way body digest only, never payloads or secrets. Break-glass sessions are always recorded. Continuing requires acknowledging this notice.`,ack:`Acknowledge and continue`,ackDone:`Recording notice acknowledged`,cancel:`Cancel`},policy:{title:`Recording policy`,subtitle:`What is recorded on this control plane, and how the evidence is classified. Editing requires the recording:config:admin permission; every change here is itself a recorded privileged action.`,loading:`Loading recording policy…`,saved:`Recording policy saved`,save:`Save policy`,saveFailed:`The policy was not saved.`,forbidden:{title:`Editing the recording policy requires recording:config:admin`,description:`Your role can administer recording sessions, but changing the recording policy needs the distinct recording:config:admin permission. Ask an administrator to grant it.`},error:{title:`Could not load the recording policy`,description:`The recording policy could not be read. Retry, or check that the module is mounted.`},breakglass:{label:`Break-glass sessions`,hint:`Emergency break-glass access is always recorded — no policy can turn it off. The recording floor is permission-based, not namespace-based.`,badge:`Always on`},namespaces:{label:`Recorded namespaces`,hint:`The module surfaces whose privileged actions are captured. Each must name a mounted module; an unknown name is rejected by the server.`,empty:`No namespaces recorded — privileged actions are not captured on any module surface.`,placeholder:`e.g. governance`,addLabel:`Add a recorded namespace`,add:`Add`,remove:`Remove {{name}}`,shape:`A namespace is lowercase letters, digits, - or _, starting with a letter and not ending in - or _.`,duplicate:`That namespace is already in the list.`,tooLong:`A namespace is at most {{max}} characters.`,tooMany:`At most {{max}} namespaces can be recorded.`},consent:{label:`Require acknowledgement before privileged actions`,hint:`Deny-closed ("required"): operators must acknowledge the AC-8 recording notice before acting. Off leaves the notice as a banner only ("notice").`},idle:{label:`Idle-seal timeout (seconds)`,hint:`An open recording session is sealed after this much inactivity. Between 60 and 86400 seconds.`,error:`Enter a whole number of seconds between 60 and 86400.`},retention:{label:`Retention class (days)`,hint:`A classification tag applied to sealed recordings — it labels how long they should be kept. Between 1 and 3650 days.`,tag:`Tag only`,enforced:`Enforced`,notEnforced:`Retention is a classification tag only — recordings are labelled, never purged. No policy removes a recording yet (no purge is wired).`,error:`Enter a whole number of days between 1 and 3650.`},ai:{label:`AI-derived summaries`,hint:`Allow generating model-derived session summaries. A summary is a derived narrative, never evidence — the hash-chained frames remain the record.`}}},es:{title:`Grabaciones`,subtitle:`Grabación de sesiones privilegiadas: cada acción administrativa sobre una superficie grabada se captura como un frame encadenado por hash y anclado al registro de evidencia.`,search:{field:`Campo de búsqueda`,subject:`El sujeto contiene`,grant:`ID del grant`,input:`Buscar grabaciones`,subjectPlaceholder:`Texto del sujeto`,grantPlaceholder:`ID exacto del grant`,submit:`Buscar`,clear:`Limpiar`},allStatuses:`Todos los estados`,filterByStatus:`Filtrar por estado`,filterBySealReason:`Filtrar por motivo de sellado`,allSealReasons:`Todos los motivos de sellado`,filterOpenedAfter:`Abierta después de`,filterOpenedBefore:`Abierta antes de`,sealReasonOption:{idle:`Inactiva`,closed:`Cerrada`,breakglass_review:`Revisión break-glass`,sweep:`Barrido`,consent_change:`Cambio de consentimiento`},status:{active:`Activa`,sealed:`Sellada`},kind:{user:`Usuario`,token:`Token`},cols:{subject:`Sujeto`,kind:`Tipo`,status:`Estado`,opened:`Abierta`,frames:`Frames escritos`,flags:`Indicadores`,sealReason:`Motivo de sellado`},badge:{gap:`GAP`,gapHint:`Se reservaron frames que nunca se escribieron: la grabación tiene un hueco permanente y evidente.`,breakglass:`Break-glass`,breakglassHint:`Abierta bajo un grant de break-glass — siempre se graba.`},empty:{title:`Aún no hay sesiones de grabación`,description:`Cuando los operadores actúen sobre una superficie privilegiada grabada, sus sesiones aparecerán aquí.`},notice:{strip:`Esta es una superficie privilegiada grabada: las acciones se capturan en el registro de evidencia.`},consent:{title:`Aviso de grabación (AC-8)`,body:`Las acciones privilegiadas en este plano de control se graban: cada petición administrativa se captura como un frame encadenado por hash y anclado al registro de evidencia — solo la forma de la ruta, identificadores y un digest unidireccional del cuerpo; nunca payloads ni secretos. Las sesiones break-glass se graban siempre. Para continuar es necesario aceptar este aviso.`,ack:`Aceptar y continuar`,ackDone:`Aviso de grabación aceptado`,cancel:`Cancelar`},policy:{title:`Política de grabación`,subtitle:`Qué se graba en este plano de control y cómo se clasifica la evidencia. Editar requiere el permiso recording:config:admin; cada cambio aquí es en sí mismo una acción privilegiada grabada.`,loading:`Cargando la política de grabación…`,saved:`Política de grabación guardada`,save:`Guardar política`,saveFailed:`La política no se guardó.`,forbidden:{title:`Editar la política de grabación requiere recording:config:admin`,description:`Tu rol puede administrar las sesiones de grabación, pero cambiar la política de grabación necesita el permiso distinto recording:config:admin. Pídele a un administrador que te lo conceda.`},error:{title:`No se pudo cargar la política de grabación`,description:`No se pudo leer la política de grabación. Reinténtalo o comprueba que el módulo esté montado.`},breakglass:{label:`Sesiones break-glass`,hint:`El acceso de emergencia break-glass siempre se graba: ninguna política puede desactivarlo. El suelo de grabación se basa en permisos, no en espacios de nombres.`,badge:`Siempre activo`},namespaces:{label:`Espacios de nombres grabados`,hint:`Las superficies de módulo cuyas acciones privilegiadas se capturan. Cada una debe nombrar un módulo montado; un nombre desconocido lo rechaza el servidor.`,empty:`No hay espacios de nombres grabados: no se capturan acciones privilegiadas en ninguna superficie de módulo.`,placeholder:`p. ej. governance`,addLabel:`Añadir un espacio de nombres grabado`,add:`Añadir`,remove:`Eliminar {{name}}`,shape:`Un espacio de nombres son letras minúsculas, dígitos, - o _, empieza por una letra y no termina en - ni _.`,duplicate:`Ese espacio de nombres ya está en la lista.`,tooLong:`Un espacio de nombres tiene como máximo {{max}} caracteres.`,tooMany:`Se pueden grabar como máximo {{max}} espacios de nombres.`},consent:{label:`Exigir aceptación antes de las acciones privilegiadas`,hint:`Cerrado por defecto ("required"): los operadores deben aceptar el aviso de grabación AC-8 antes de actuar. Desactivado deja el aviso solo como banner ("notice").`},idle:{label:`Tiempo de sellado por inactividad (segundos)`,hint:`Una sesión de grabación abierta se sella tras esta inactividad. Entre 60 y 86400 segundos.`,error:`Introduce un número entero de segundos entre 60 y 86400.`},retention:{label:`Clase de retención (días)`,hint:`Una etiqueta de clasificación aplicada a las grabaciones selladas: indica cuánto deberían conservarse. Entre 1 y 3650 días.`,tag:`Solo etiqueta`,enforced:`Aplicada`,notEnforced:`La retención es solo una etiqueta de clasificación: las grabaciones se etiquetan, nunca se purgan. Ninguna política elimina todavía una grabación (no hay purga cableada).`,error:`Introduce un número entero de días entre 1 y 3650.`},ai:{label:`Resúmenes derivados por IA`,hint:`Permitir generar resúmenes de sesión derivados de un modelo. Un resumen es una narrativa derivada, nunca evidencia: el registro son los frames encadenados por hash.`}}},zh:{title:`录制`,subtitle:`特权会话录制——录制范围内的每一项管理操作都会被捕获为哈希链帧，并锚定到证据账本。`,search:{field:`搜索字段`,subject:`主体包含`,grant:`授权 ID`,input:`搜索录制`,subjectPlaceholder:`主体文本`,grantPlaceholder:`精确授权 ID`,submit:`搜索`,clear:`清除`},allStatuses:`全部状态`,filterByStatus:`按状态筛选`,filterBySealReason:`按封存原因筛选`,allSealReasons:`全部封存原因`,filterOpenedAfter:`开启时间晚于`,filterOpenedBefore:`开启时间早于`,sealReasonOption:{idle:`空闲`,closed:`已关闭`,breakglass_review:`应急破窗审查`,sweep:`清理`,consent_change:`同意变更`},status:{active:`活跃`,sealed:`已封存`},kind:{user:`用户`,token:`令牌`},cols:{subject:`主体`,kind:`类型`,status:`状态`,opened:`开启时间`,frames:`已写入帧数`,flags:`标记`,sealReason:`封存原因`},badge:{gap:`缺口`,gapHint:`帧已预留但从未写入——该录制存在永久且明显的缺口。`,breakglass:`应急破窗`,breakglassHint:`在应急破窗授权下开启——始终录制。`},empty:{title:`暂无录制会话`,description:`当操作人员在录制范围内的特权操作面上执行操作时，其会话将显示在此处。`},notice:{strip:`这是一个录制范围内的特权操作面——操作将被捕获到证据账本。`},consent:{title:`录制提示（AC-8）`,body:`此控制平面上的特权操作会被录制：每个管理请求都会被捕获为锚定到证据账本的哈希链帧——仅包含路由结构、标识符和单向的请求体摘要，绝不包含载荷或密钥。应急破窗会话始终录制。继续操作前必须确认此通知。`,ack:`确认并继续`,ackDone:`已确认录制提示`,cancel:`取消`},policy:{title:`录制策略`,subtitle:`此控制平面上录制什么，以及如何对证据进行分类。编辑需要 recording:config:admin 权限；此处的每次更改本身也是被录制的特权操作。`,loading:`正在加载录制策略…`,saved:`录制策略已保存`,save:`保存策略`,saveFailed:`策略未保存。`,forbidden:{title:`编辑录制策略需要 recording:config:admin`,description:`你的角色可以管理录制会话，但更改录制策略需要单独的 recording:config:admin 权限。请管理员授予该权限。`},error:{title:`无法加载录制策略`,description:`无法读取录制策略。请重试，或检查模块是否已挂载。`},breakglass:{label:`破窗（break-glass）会话`,hint:`紧急破窗访问始终被录制——任何策略都无法将其关闭。录制下限基于权限，而非命名空间。`,badge:`始终开启`},namespaces:{label:`录制的命名空间`,hint:`其特权操作被捕获的模块面。每个都必须命名一个已挂载的模块；未知名称会被服务器拒绝。`,empty:`未录制任何命名空间——任何模块面上都不会捕获特权操作。`,placeholder:`例如 governance`,addLabel:`添加录制的命名空间`,add:`添加`,remove:`移除 {{name}}`,shape:`命名空间由小写字母、数字、- 或 _ 组成，以字母开头，且不以 - 或 _ 结尾。`,duplicate:`该命名空间已在列表中。`,tooLong:`命名空间最多 {{max}} 个字符。`,tooMany:`最多可录制 {{max}} 个命名空间。`},consent:{label:`在特权操作前要求确认`,hint:`默认拒绝（"required"）：操作员必须先确认 AC-8 录制通知才能操作。关闭时通知仅作为横幅（"notice"）。`},idle:{label:`空闲封存超时（秒）`,hint:`打开的录制会话在此时长无活动后被封存。介于 60 到 86400 秒之间。`,error:`请输入 60 到 86400 之间的整数秒。`},retention:{label:`保留类别（天）`,hint:`应用于已封存录制的分类标签——它标示应保留多久。介于 1 到 3650 天之间。`,tag:`仅标签`,enforced:`已强制`,notEnforced:`保留只是一个分类标签——录制仅被打标签，绝不清除。目前没有任何策略会删除录制（未接入清除）。`,error:`请输入 1 到 3650 之间的整数天数。`},ai:{label:`AI 生成的摘要`,hint:`允许生成模型派生的会话摘要。摘要是派生叙述，绝非证据——哈希链帧才是记录。`}}},ja:{title:`記録`,subtitle:`特権セッションの記録 — 記録対象サーフェス上のすべての管理操作は、ハッシュチェーン化されたフレームとして取得され、証拠台帳にアンカーされます。`,search:{field:`検索フィールド`,subject:`サブジェクトを含む`,grant:`付与 ID`,input:`記録を検索`,subjectPlaceholder:`サブジェクトの文字列`,grantPlaceholder:`正確な付与 ID`,submit:`検索`,clear:`クリア`},allStatuses:`すべてのステータス`,filterByStatus:`ステータスで絞り込み`,filterBySealReason:`封印理由で絞り込み`,allSealReasons:`すべての封印理由`,filterOpenedAfter:`開始日（以降）`,filterOpenedBefore:`開始日（以前）`,sealReasonOption:{idle:`アイドル`,closed:`クローズ`,breakglass_review:`ブレークグラスレビュー`,sweep:`スイープ`,consent_change:`同意変更`},status:{active:`アクティブ`,sealed:`封印済み`},kind:{user:`ユーザー`,token:`トークン`},cols:{subject:`サブジェクト`,kind:`種別`,status:`ステータス`,opened:`開始`,frames:`書き込み済みフレーム数`,flags:`フラグ`,sealReason:`封印理由`},badge:{gap:`ギャップ`,gapHint:`フレームは予約されましたが書き込まれませんでした — この記録には永続的で明白なギャップがあります。`,breakglass:`ブレークグラス`,breakglassHint:`ブレークグラス付与のもとで開始されました — 常に記録されます。`},empty:{title:`記録セッションはまだありません`,description:`オペレーターが記録対象の特権サーフェス上で操作すると、そのセッションがここに表示されます。`},notice:{strip:`これは記録対象の特権サーフェスです — 操作は証拠台帳に取得されます。`},consent:{title:`記録に関する通知（AC-8）`,body:`このコントロールプレーン上の特権操作は記録されます。各管理リクエストは、証拠台帳にアンカーされたハッシュチェーン化されたフレームとして取得されます — ルート形状、識別子、および一方向のボディダイジェストのみであり、ペイロードやシークレットは含まれません。ブレークグラスセッションは常に記録されます。続行するには、この通知への承諾が必要です。`,ack:`承諾して続行`,ackDone:`記録に関する通知を承諾しました`,cancel:`キャンセル`},policy:{title:`記録ポリシー`,subtitle:`このコントロールプレーンで何を記録し、証跡をどう分類するか。編集には recording:config:admin 権限が必要です。ここでの変更自体も記録される特権操作です。`,loading:`記録ポリシーを読み込み中…`,saved:`記録ポリシーを保存しました`,save:`ポリシーを保存`,saveFailed:`ポリシーは保存されませんでした。`,forbidden:{title:`記録ポリシーの編集には recording:config:admin が必要です`,description:`あなたのロールは記録セッションを管理できますが、記録ポリシーの変更には別個の recording:config:admin 権限が必要です。管理者に付与を依頼してください。`},error:{title:`記録ポリシーを読み込めませんでした`,description:`記録ポリシーを読み取れませんでした。再試行するか、モジュールがマウントされているか確認してください。`},breakglass:{label:`ブレークグラスセッション`,hint:`緊急のブレークグラスアクセスは常に記録され、どのポリシーでも無効化できません。記録の下限は名前空間ではなく権限に基づきます。`,badge:`常時オン`},namespaces:{label:`記録対象の名前空間`,hint:`特権操作が記録されるモジュール面。それぞれマウント済みのモジュールを指定する必要があり、未知の名前はサーバーに拒否されます。`,empty:`記録対象の名前空間はありません — どのモジュール面でも特権操作は記録されません。`,placeholder:`例: governance`,addLabel:`記録対象の名前空間を追加`,add:`追加`,remove:`{{name}} を削除`,shape:`名前空間は小文字・数字・- または _ で構成し、文字で始まり - または _ では終わりません。`,duplicate:`その名前空間はすでにリストにあります。`,tooLong:`名前空間は最大 {{max}} 文字です。`,tooMany:`記録できる名前空間は最大 {{max}} 個です。`},consent:{label:`特権操作の前に承認を必須にする`,hint:`デフォルト拒否("required"):オペレーターは操作前に AC-8 記録通知を承認する必要があります。オフの場合、通知はバナーのみ("notice")です。`},idle:{label:`アイドルシール時間(秒)`,hint:`開いている記録セッションは、この非アクティブ時間の後にシールされます。60〜86400 秒。`,error:`60〜86400 の整数秒を入力してください。`},retention:{label:`保持クラス(日)`,hint:`シール済みの記録に付与される分類タグ — どれくらい保持すべきかを示します。1〜3650 日。`,tag:`タグのみ`,enforced:`適用済み`,notEnforced:`保持は分類タグのみです — 記録はラベル付けされるだけで、パージされることはありません。まだ記録を削除するポリシーはありません(パージは未配線)。`,error:`1〜3650 の整数日を入力してください。`},ai:{label:`AI 生成の要約`,hint:`モデル由来のセッション要約の生成を許可します。要約は派生的な説明であり証跡ではありません — ハッシュ連鎖されたフレームが記録です。`}}},de:{title:`Aufzeichnungen`,subtitle:`Aufzeichnung privilegierter Sitzungen — jede administrative Aktion auf einer aufgezeichneten Oberfläche wird als Hash-verkettetes Frame erfasst und im Nachweis-Hauptbuch verankert.`,search:{field:`Suchfeld`,subject:`Subjekt enthält`,grant:`Berechtigungs-ID`,input:`Aufzeichnungen durchsuchen`,subjectPlaceholder:`Subjekttext`,grantPlaceholder:`Exakte Berechtigungs-ID`,submit:`Suchen`,clear:`Leeren`},allStatuses:`Alle Status`,filterByStatus:`Nach Status filtern`,filterBySealReason:`Nach Versiegelungsgrund filtern`,allSealReasons:`Alle Versiegelungsgründe`,filterOpenedAfter:`Geöffnet nach`,filterOpenedBefore:`Geöffnet vor`,sealReasonOption:{idle:`Inaktiv`,closed:`Geschlossen`,breakglass_review:`Notfallzugriff-Überprüfung`,sweep:`Bereinigung`,consent_change:`Einwilligungsänderung`},status:{active:`Aktiv`,sealed:`Versiegelt`},kind:{user:`Benutzer`,token:`Token`},cols:{subject:`Subjekt`,kind:`Art`,status:`Status`,opened:`Geöffnet`,frames:`Geschriebene Frames`,flags:`Markierungen`,sealReason:`Versiegelungsgrund`},badge:{gap:`LÜCKE`,gapHint:`Frames wurden reserviert, aber nie geschrieben — die Aufzeichnung weist eine dauerhafte, nachweisbare Lücke auf.`,breakglass:`Notfallzugriff`,breakglassHint:`Unter einer Notfallzugriff-Gewährung geöffnet — wird stets aufgezeichnet.`},empty:{title:`Noch keine Aufzeichnungssitzungen`,description:`Sobald Operatoren auf einer aufgezeichneten privilegierten Oberfläche tätig werden, erscheinen ihre Sitzungen hier.`},notice:{strip:`Dies ist eine aufgezeichnete privilegierte Oberfläche — Aktionen werden im Nachweis-Hauptbuch erfasst.`},consent:{title:`Aufzeichnungshinweis (AC-8)`,body:`Privilegierte Aktionen auf dieser Steuerungsebene werden aufgezeichnet: Jede administrative Anfrage wird als Hash-verkettetes Frame erfasst und im Nachweis-Hauptbuch verankert — ausschließlich Routenform, Bezeichner und ein Einweg-Digest des Inhalts, niemals Nutzdaten oder Geheimnisse. Notfallzugriff-Sitzungen werden stets aufgezeichnet. Zum Fortfahren ist die Bestätigung dieses Hinweises erforderlich.`,ack:`Bestätigen und fortfahren`,ackDone:`Aufzeichnungshinweis bestätigt`,cancel:`Abbrechen`},policy:{title:`Aufzeichnungsrichtlinie`,subtitle:`Was auf dieser Steuerungsebene aufgezeichnet wird und wie die Nachweise klassifiziert werden. Bearbeiten erfordert die Berechtigung recording:config:admin; jede Änderung hier ist selbst eine aufgezeichnete privilegierte Aktion.`,loading:`Aufzeichnungsrichtlinie wird geladen …`,saved:`Aufzeichnungsrichtlinie gespeichert`,save:`Richtlinie speichern`,saveFailed:`Die Richtlinie wurde nicht gespeichert.`,forbidden:{title:`Das Bearbeiten der Aufzeichnungsrichtlinie erfordert recording:config:admin`,description:`Ihre Rolle kann Aufzeichnungssitzungen verwalten, aber das Ändern der Aufzeichnungsrichtlinie benötigt die eigene Berechtigung recording:config:admin. Bitten Sie eine Administratorin oder einen Administrator, sie zu erteilen.`},error:{title:`Aufzeichnungsrichtlinie konnte nicht geladen werden`,description:`Die Aufzeichnungsrichtlinie konnte nicht gelesen werden. Erneut versuchen oder prüfen, ob das Modul eingebunden ist.`},breakglass:{label:`Break-Glass-Sitzungen`,hint:`Break-Glass-Notzugriff wird immer aufgezeichnet — keine Richtlinie kann ihn abschalten. Die Aufzeichnungsuntergrenze basiert auf Berechtigungen, nicht auf Namensräumen.`,badge:`Immer an`},namespaces:{label:`Aufgezeichnete Namensräume`,hint:`Die Modulflächen, deren privilegierte Aktionen erfasst werden. Jeder muss ein eingebundenes Modul benennen; ein unbekannter Name wird vom Server abgelehnt.`,empty:`Keine Namensräume aufgezeichnet — auf keiner Modulfläche werden privilegierte Aktionen erfasst.`,placeholder:`z. B. governance`,addLabel:`Aufgezeichneten Namensraum hinzufügen`,add:`Hinzufügen`,remove:`{{name}} entfernen`,shape:`Ein Namensraum besteht aus Kleinbuchstaben, Ziffern, - oder _, beginnt mit einem Buchstaben und endet nicht mit - oder _.`,duplicate:`Dieser Namensraum steht bereits in der Liste.`,tooLong:`Ein Namensraum hat höchstens {{max}} Zeichen.`,tooMany:`Es können höchstens {{max}} Namensräume aufgezeichnet werden.`},consent:{label:`Bestätigung vor privilegierten Aktionen verlangen`,hint:`Standardmäßig verweigernd ("required"): Bedienende müssen den AC-8-Aufzeichnungshinweis bestätigen, bevor sie handeln. Aus lässt den Hinweis nur als Banner ("notice").`},idle:{label:`Leerlauf-Versiegelungszeit (Sekunden)`,hint:`Eine offene Aufzeichnungssitzung wird nach dieser Inaktivität versiegelt. Zwischen 60 und 86400 Sekunden.`,error:`Geben Sie eine ganze Zahl von Sekunden zwischen 60 und 86400 ein.`},retention:{label:`Aufbewahrungsklasse (Tage)`,hint:`Ein Klassifizierungs-Tag für versiegelte Aufzeichnungen — es kennzeichnet, wie lange sie aufbewahrt werden sollten. Zwischen 1 und 3650 Tagen.`,tag:`Nur Tag`,enforced:`Erzwungen`,notEnforced:`Aufbewahrung ist nur ein Klassifizierungs-Tag — Aufzeichnungen werden gekennzeichnet, nie bereinigt. Keine Richtlinie entfernt bislang eine Aufzeichnung (keine Bereinigung verdrahtet).`,error:`Geben Sie eine ganze Zahl von Tagen zwischen 1 und 3650 ein.`},ai:{label:`KI-abgeleitete Zusammenfassungen`,hint:`Erlaubt das Erzeugen modellabgeleiteter Sitzungszusammenfassungen. Eine Zusammenfassung ist eine abgeleitete Erzählung, nie ein Nachweis — die hash-verketteten Frames bleiben der Nachweis.`}}},ru:{title:`Записи`,subtitle:`Запись привилегированных сессий — каждое административное действие на записываемой поверхности фиксируется как кадр в цепочке хешей, привязанный к реестру доказательств.`,search:{field:`Поле поиска`,subject:`Субъект содержит`,grant:`ID разрешения`,input:`Поиск записей`,subjectPlaceholder:`Текст субъекта`,grantPlaceholder:`Точный ID разрешения`,submit:`Найти`,clear:`Очистить`},allStatuses:`Все статусы`,filterByStatus:`Фильтр по статусу`,filterBySealReason:`Фильтр по причине запечатывания`,allSealReasons:`Все причины запечатывания`,filterOpenedAfter:`Открыто после`,filterOpenedBefore:`Открыто до`,sealReasonOption:{idle:`Простой`,closed:`Закрыто`,breakglass_review:`Проверка режима экстренного доступа`,sweep:`Очистка`,consent_change:`Изменение согласия`},status:{active:`Активно`,sealed:`Запечатано`},kind:{user:`Пользователь`,token:`Токен`},cols:{subject:`Субъект`,kind:`Тип`,status:`Статус`,opened:`Открыто`,frames:`Записано кадров`,flags:`Флаги`,sealReason:`Причина запечатывания`},badge:{gap:`ПРОПУСК`,gapHint:`Кадры были зарезервированы, но так и не записаны — в записи есть постоянный, явный пропуск.`,breakglass:`Режим экстренного доступа`,breakglassHint:`Открыто по гранту режима экстренного доступа — всегда записывается.`},empty:{title:`Пока нет сессий записи`,description:`Когда операторы выполняют действия на записываемой привилегированной поверхности, их сессии появляются здесь.`},notice:{strip:`Это записываемая привилегированная поверхность — действия фиксируются в реестре доказательств.`},consent:{title:`Уведомление о записи (AC-8)`,body:`Привилегированные действия на этой плоскости управления записываются: каждый административный запрос фиксируется как кадр в цепочке хешей, привязанный к реестру доказательств — только форма маршрута, идентификаторы и односторонний дайджест тела запроса, никогда сами данные или секреты. Сессии в режиме экстренного доступа записываются всегда. Для продолжения необходимо подтвердить ознакомление с этим уведомлением.`,ack:`Подтвердить и продолжить`,ackDone:`Уведомление о записи подтверждено`,cancel:`Отменить`},policy:{title:`Политика записи`,subtitle:`Что записывается на этой плоскости управления и как классифицируются доказательства. Редактирование требует разрешения recording:config:admin; каждое изменение здесь само является записываемым привилегированным действием.`,loading:`Загрузка политики записи…`,saved:`Политика записи сохранена`,save:`Сохранить политику`,saveFailed:`Политика не была сохранена.`,forbidden:{title:`Для редактирования политики записи нужно recording:config:admin`,description:`Ваша роль может администрировать сессии записи, но изменение политики записи требует отдельного разрешения recording:config:admin. Попросите администратора выдать его.`},error:{title:`Не удалось загрузить политику записи`,description:`Не удалось прочитать политику записи. Повторите попытку или проверьте, что модуль смонтирован.`},breakglass:{label:`Сессии break-glass`,hint:`Аварийный доступ break-glass записывается всегда — ни одна политика не может его отключить. Нижний порог записи основан на разрешениях, а не на пространствах имён.`,badge:`Всегда включено`},namespaces:{label:`Записываемые пространства имён`,hint:`Поверхности модулей, чьи привилегированные действия захватываются. Каждое должно называть смонтированный модуль; неизвестное имя отклоняется сервером.`,empty:`Пространства имён не записываются — привилегированные действия не захватываются ни на одной поверхности модуля.`,placeholder:`напр. governance`,addLabel:`Добавить записываемое пространство имён`,add:`Добавить`,remove:`Удалить {{name}}`,shape:`Пространство имён состоит из строчных букв, цифр, - или _, начинается с буквы и не заканчивается на - или _.`,duplicate:`Это пространство имён уже есть в списке.`,tooLong:`Пространство имён содержит не более {{max}} символов.`,tooMany:`Можно записывать не более {{max}} пространств имён.`},consent:{label:`Требовать подтверждение перед привилегированными действиями`,hint:`Закрыто по умолчанию ("required"): операторы должны подтвердить уведомление о записи AC-8 перед действием. При выключении уведомление остаётся только баннером ("notice").`},idle:{label:`Тайм-аут запечатывания по простою (секунды)`,hint:`Открытая сессия записи запечатывается после такого простоя. От 60 до 86400 секунд.`,error:`Введите целое число секунд от 60 до 86400.`},retention:{label:`Класс хранения (дни)`,hint:`Классификационный тег для запечатанных записей — он указывает, как долго их следует хранить. От 1 до 3650 дней.`,tag:`Только тег`,enforced:`Применяется`,notEnforced:`Хранение — это только классификационный тег: записи помечаются, но никогда не очищаются. Пока ни одна политика не удаляет запись (очистка не подключена).`,error:`Введите целое число дней от 1 до 3650.`},ai:{label:`Сводки, полученные ИИ`,hint:`Разрешить создание сводок сессий, полученных моделью. Сводка — это производный рассказ, а не доказательство: записью остаются кадры, связанные хешем.`}}},fr:{title:`Enregistrements`,subtitle:`Enregistrement des sessions privilégiées — chaque action administrative sur une surface enregistrée est capturée sous forme de trame chaînée par hachage, ancrée au registre de preuves.`,search:{field:`Champ de recherche`,subject:`Le sujet contient`,grant:`ID d’octroi`,input:`Rechercher des enregistrements`,subjectPlaceholder:`Texte du sujet`,grantPlaceholder:`ID d’octroi exact`,submit:`Rechercher`,clear:`Effacer`},allStatuses:`Tous les statuts`,filterByStatus:`Filtrer par statut`,filterBySealReason:`Filtrer par motif de scellement`,allSealReasons:`Tous les motifs de scellement`,filterOpenedAfter:`Ouvert après`,filterOpenedBefore:`Ouvert avant`,sealReasonOption:{idle:`Inactif`,closed:`Fermé`,breakglass_review:`Révision d'accès d'urgence`,sweep:`Balayage`,consent_change:`Modification du consentement`},status:{active:`Actif`,sealed:`Scellé`},kind:{user:`Utilisateur`,token:`Token`},cols:{subject:`Sujet`,kind:`Type`,status:`Statut`,opened:`Ouvert`,frames:`Trames écrites`,flags:`Indicateurs`,sealReason:`Motif du scellement`},badge:{gap:`LACUNE`,gapHint:`Des trames ont été réservées mais jamais écrites — l’enregistrement présente une lacune permanente et manifeste.`,breakglass:`Accès d’urgence`,breakglassHint:`Ouvert dans le cadre d’un octroi d’accès d’urgence — toujours enregistré.`},empty:{title:`Aucune session d’enregistrement pour l’instant`,description:`Lorsque les opérateurs agissent sur une surface privilégiée enregistrée, leurs sessions apparaissent ici.`},notice:{strip:`Ceci est une surface privilégiée enregistrée — les actions sont capturées dans le registre de preuves.`},consent:{title:`Avis d’enregistrement (AC-8)`,body:`Les actions privilégiées sur ce plan de contrôle sont enregistrées : chaque requête administrative est capturée sous forme de trame chaînée par hachage et ancrée au registre de preuves — uniquement la forme de la route, les identifiants et un condensé unidirectionnel du corps, jamais les charges utiles ni les secrets. Les sessions d’accès d’urgence sont toujours enregistrées. Pour continuer, vous devez accuser réception de cet avis.`,ack:`Accuser réception et continuer`,ackDone:`Avis d’enregistrement pris en compte`,cancel:`Annuler`},policy:{title:`Politique d’enregistrement`,subtitle:`Ce qui est enregistré sur ce plan de contrôle et comment les preuves sont classées. La modification requiert la permission recording:config:admin ; chaque changement ici est lui-même une action privilégiée enregistrée.`,loading:`Chargement de la politique d’enregistrement…`,saved:`Politique d’enregistrement enregistrée`,save:`Enregistrer la politique`,saveFailed:`La politique n’a pas été enregistrée.`,forbidden:{title:`Modifier la politique d’enregistrement requiert recording:config:admin`,description:`Votre rôle peut administrer les sessions d’enregistrement, mais modifier la politique d’enregistrement nécessite la permission distincte recording:config:admin. Demandez à un administrateur de vous l’accorder.`},error:{title:`Impossible de charger la politique d’enregistrement`,description:`La politique d’enregistrement n’a pas pu être lue. Réessayez ou vérifiez que le module est monté.`},breakglass:{label:`Sessions break-glass`,hint:`L’accès d’urgence break-glass est toujours enregistré — aucune politique ne peut le désactiver. Le plancher d’enregistrement repose sur les permissions, pas sur les espaces de noms.`,badge:`Toujours actif`},namespaces:{label:`Espaces de noms enregistrés`,hint:`Les surfaces de module dont les actions privilégiées sont capturées. Chacun doit nommer un module monté ; un nom inconnu est rejeté par le serveur.`,empty:`Aucun espace de noms enregistré — les actions privilégiées ne sont capturées sur aucune surface de module.`,placeholder:`p. ex. governance`,addLabel:`Ajouter un espace de noms enregistré`,add:`Ajouter`,remove:`Supprimer {{name}}`,shape:`Un espace de noms est composé de lettres minuscules, chiffres, - ou _, commence par une lettre et ne se termine pas par - ni _.`,duplicate:`Cet espace de noms est déjà dans la liste.`,tooLong:`Un espace de noms fait au plus {{max}} caractères.`,tooMany:`Au plus {{max}} espaces de noms peuvent être enregistrés.`},consent:{label:`Exiger l’acquittement avant les actions privilégiées`,hint:`Fermé par défaut ("required") : les opérateurs doivent acquitter l’avis d’enregistrement AC-8 avant d’agir. Désactivé, l’avis reste une simple bannière ("notice").`},idle:{label:`Délai de scellement par inactivité (secondes)`,hint:`Une session d’enregistrement ouverte est scellée après cette inactivité. Entre 60 et 86400 secondes.`,error:`Saisissez un nombre entier de secondes entre 60 et 86400.`},retention:{label:`Classe de rétention (jours)`,hint:`Une étiquette de classification appliquée aux enregistrements scellés — elle indique combien de temps ils devraient être conservés. Entre 1 et 3650 jours.`,tag:`Étiquette seule`,enforced:`Appliquée`,notEnforced:`La rétention n’est qu’une étiquette de classification — les enregistrements sont étiquetés, jamais purgés. Aucune politique ne supprime encore un enregistrement (aucune purge n’est câblée).`,error:`Saisissez un nombre entier de jours entre 1 et 3650.`},ai:{label:`Résumés dérivés par IA`,hint:`Autoriser la génération de résumés de session dérivés d’un modèle. Un résumé est un récit dérivé, jamais une preuve — les frames chaînés par hash restent l’enregistrement.`}}}});var y=i();function b({namespace:e,always:n=!1,className:i}){let{t:b}=t(`recordings`),{activeTenant:x}=o(),S=r({queryKey:g.notice(x),queryFn:()=>_.notice()}),C=m({mutationFn:()=>_.acknowledge(),invalidateKeys:[g.all(x)],successMessage:b(`consent.ackDone`)}),w=S.data;return!w||!n&&!w.recorded_namespaces?.includes(e)?null:(0,y.jsxs)(y.Fragment,{children:[(0,y.jsx)(s,{tone:`info`,icon:(0,y.jsx)(v,{}),className:i,children:(0,y.jsx)(`span`,{className:`text-muted-foreground`,children:b(`notice.strip`)})}),(0,y.jsx)(h,{open:w.consent_required,children:(0,y.jsxs)(c,{hideClose:!0,children:[(0,y.jsxs)(d,{children:[(0,y.jsx)(p,{children:b(`consent.title`)}),(0,y.jsx)(f,{children:b(`consent.body`)})]}),(0,y.jsxs)(u,{children:[(0,y.jsx)(a,{variant:`secondary`,onClick:()=>window.history.back(),disabled:C.isPending,children:b(`consent.cancel`)}),(0,y.jsxs)(a,{variant:`primary`,onClick:()=>C.mutate(void 0),disabled:C.isPending,children:[C.isPending&&(0,y.jsx)(l,{size:`sm`,"aria-hidden":!0}),b(`consent.ack`)]})]})]})})]})}export{b as t};